 if(mime) cv={...cv,mimeType:mime,fileName:'CV.'+(isPdf?'pdf':isPng?'png':'jpg')};
}
const now=new Date().toISOString();
return [{json:{candidate_id:'CAN-V3-'+$execution.id,full_name,email,job_id,phone:clean(r.phone,40),cover_letter:clean(r.cover_letter,4000),applied_at:now,consent_at:now,application_key:email+'|'+job_id,cv_file_name:file_name,cv_mime_type:mime,processing_execution_id:String($execution.id),valid:issues.length===0,email_valid,issues:issues.join(' '),source_type:'application_form',cv_source:'Google Drive',status:'received'},binary:cv?{cv}:{}}];

